</head>
<body>
<div class="card" id="root"></div>
<pre id="raw" style="display:none">$1</pre>
<script>
(function(){
  var raw=document.getElementById('raw').textContent;
  var selected=[];

  function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function get(f){
    var re=new RegExp('\\[\\s*'+f+'\\s*[|:：]\\s*([\\s\\S]+?)\\s*\\](?=\\s*(?:\\[|$))','i');
    var m=re.exec(raw);return m?m[1].trim():'';
  }
  var LV_MAP={'一重':1,'二重':2,'三重':3,'四重':4,'五重':5,'六重':6,'七重':7,'八重':8,'九重':9,'十重':10};
  var REALM_COLOR=['','#a0a0a0','#81ecec','#74b9ff','#ffeaa7','#fdcb6e','#e17055','#d63031','#6c5ce7','#fd79a8','#c8a84b'];

  var name=get('秘境名称');var lv=get('等级');var lvVal=parseInt(get('等级值'))||LV_MAP[lv]||1;
  var env=get('环境描述');var threat=get('主要威胁');var chance=get('特殊机缘');var matLim=get('灵材上限');
  var lvColor=REALM_COLOR[lvVal]||'var(--purple)';

  // 读取弟子列表
  var discs=[];
  try{
    var vars=(typeof getAllVariables==='function')?getAllVariables():{};
    var dd=_.get(vars,'stat_data.内门弟子',{});
    var dutyData=_.get(vars,'stat_data.宗派.宗门职务',{});
    var dutyNames=Object.values(dutyData).filter(Boolean);
    Object.keys(dd).forEach(function(n){
      if(!n||n.startsWith('$'))return;
      var d=dd[n];
      var coreLoc=_.get(d,'核心位置','宗门');
      // 核心位置不是宗门则不可派遣（无字段视为在宗门）
      if(coreLoc!=='宗门')return;
      var inDuty=dutyNames.indexOf(n)>=0;
      var hpNow=_.get(d,'血量.当前值',0);
      var hpMax=_.get(d,'血量.上限',1);
      var atk=_.get(d,'攻击法器.攻击力',0);
      var atkMult=1+_.get(d,'五维.力量',0)/100;
      var realAtk=Math.floor(atk*atkMult)+_.get(d,'灵兽.攻击加成',0);
      var realm=_.get(d,'修为境界','炼气期');
      var layer=_.get(d,'修为层数',1);
      discs.push({name:n,realm:realm,layer:layer,hpNow:hpNow,hpMax:hpMax,realAtk:realAtk,inDuty:inDuty});
    });
  }catch(e){}

  function buildDiscs(){
    if(!discs.length)return '<div class="no-disc">[ 暂无在宗弟子可派遣 ]</div>';
    return '<div class="disc-grid" id="dgrid">'
      +discs.map(function(d){
        var avail=!d.inDuty;
        var pct=d.hpMax>0?Math.round(d.hpNow/d.hpMax*100):0;
        var cls='disc-card'+(avail?' available':' unavailable');
        var warn=d.inDuty?'<div class="disc-warn">⚠ 担任职务中</div>':'';
        return '<div class="'+cls+'" onclick="toggle(this,\''+esc(d.name)+'\')">'
          +'<div class="disc-name">'+esc(d.name)+'</div>'
          +'<div class="disc-realm">'+esc(d.realm)+'·'+d.layer+'层</div>'
          +'<div class="hp-bar"><div class="hp-fill" style="width:'+pct+'%"></div></div>'
          +'<div class="disc-atk">实攻 '+d.realAtk+'  HP '+d.hpNow+'/'+d.hpMax+'</div>'
          +warn
          +'</div>';
      }).join('')
      +'</div>';
  }

  var html='';
  if(name){
    html+='<div class="hdr">'
      +'<span class="title">'+esc(name)+'</span>'
      +'<span class="lv-badge" style="color:'+lvColor+';border-color:'+lvColor+'40;">'+esc(lv)+'</span>'
      +'</div>'
      +'<div class="stats-row">'
      +'<div class="stat-chip stat-lv">⚡ '+esc(lv)+'（'+lvVal+'重）</div>'
      +(matLim?'<div class="stat-chip stat-mat">💎 灵材上限 '+esc(matLim)+'</div>':'')
      +'</div>'
      +(env?'<div class="info-block"><div class="info-label">灵气环境</div><div class="info-text">'+esc(env)+'</div></div>':'')
      +(threat?'<div class="info-block"><div class="info-label">主要威胁</div><div class="info-text danger">'+esc(threat)+'</div></div>':'')
      +(chance?'<div class="info-block"><div class="info-label">特殊机缘</div><div class="info-text chance">'+esc(chance)+'</div></div>':'');
  }else{
    html+='<div style="color:var(--dim);font-family:monospace;text-align:center;padding:16px">[ 秘境数据解析失败 ]</div>';
  }

  html+='<div class="sec">派遣弟子</div>'
    +buildDiscs()
    +'<div class="btn-dispatch disabled" id="btn" onclick="dispatch()">选择派遣弟子</div>';

  document.getElementById('root').innerHTML=html;

  window.toggle=function(el,n){
    if(el.classList.contains('unavailable'))return;
    var i=selected.indexOf(n);
    if(i>-1){selected.splice(i,1);el.classList.remove('selected');}
    else{if(selected.length>=3){alert('最多同时派遣3名弟子');return;}selected.push(n);el.classList.add('selected');}
    var btn=document.getElementById('btn');
    if(selected.length>0){
      btn.className='btn-dispatch ready';
      btn.textContent='⚔ 派遣 [ '+selected.join('、')+' ] 进入秘境';
    }else{
      btn.className='btn-dispatch disabled';
      btn.textContent='选择派遣弟子';
    }
  };

  window.dispatch=function(){
    var btn=document.getElementById('btn');
    if(btn.classList.contains('disabled')||btn.classList.contains('done'))return;
    var text='我派遣【'+selected.join('、')+'】前往「'+name+'」探索。';
    function done(){btn.className='btn-dispatch done';btn.textContent='[ ✓ 已填入输入框 ]';}
    try{
      var p=window.parent.document.querySelector('#send_textarea');
      if(p){var v=p.value;p.value=v?v+'\n'+text:text;p.dispatchEvent(new Event('input',{bubbles:true}));p.focus();done();return;}
    }catch(e){}
    try{navigator.clipboard.writeText(text).then(done);}catch(e){
      var el=document.createElement('textarea');el.value=text;document.body.appendChild(el);el.select();
      try{document.execCommand('copy');}catch(e2){}document.body.removeChild(el);done();
    }
  };
})();
</script>
</body>
</html>
