  content:'';display:block;height:2px;margin:-20px -20px 18px;
  background:linear-gradient(90deg,transparent,var(--gold),rgba(200,168,75,0.4),transparent);}
.hdr{display:flex;justify-content:space-between;align-items:flex-end;
  border-bottom:1px dashed rgba(200,168,75,0.25);padding-bottom:12px;margin-bottom:16px;}
.hdr-title{font-size:.9em;font-weight:700;color:var(--gold);letter-spacing:.2em;
  text-shadow:0 0 10px rgba(200,168,75,0.4);}
.hdr-status{font-size:.68em;color:var(--jade);font-family:monospace;
  text-shadow:0 0 6px rgba(78,207,154,0.4);}
.meta-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px;}
.meta-item{padding:9px 10px;border-radius:7px;
  background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.05);
  display:flex;flex-direction:column;gap:3px;}
.meta-label{font-size:.58em;color:var(--dim);letter-spacing:.06em;}
.meta-val{font-size:.85em;font-weight:700;font-family:monospace;color:var(--text);}
.meta-val.gold{color:var(--gold);text-shadow:0 0 6px rgba(200,168,75,0.3);}
.meta-val.jade{color:var(--jade);text-shadow:0 0 6px rgba(78,207,154,0.3);}
.meta-val.cyan{color:var(--cyan);text-shadow:0 0 6px rgba(92,200,212,0.3);}
.meta-val.purple{color:var(--purple);}
.meta-val.crimson{color:var(--crimson);}
.root-废灵根{color:#888;}
.root-地灵根{color:var(--silver);}
.root-天灵根{color:var(--cyan);text-shadow:0 0 6px rgba(92,200,212,0.4);}
.root-异灵根{color:var(--purple);text-shadow:0 0 6px rgba(155,114,207,0.4);}
.root-混沌灵根{color:var(--gold);text-shadow:0 0 8px rgba(200,168,75,0.5);}
.wuwei-row{display:flex;gap:6px;margin-bottom:14px;}
.ww-item{flex:1;padding:8px 6px;border-radius:6px;
  background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);
  display:flex;flex-direction:column;align-items:center;gap:3px;}
.ww-label{font-size:.58em;color:var(--dim);}
.ww-val{font-size:.9em;font-family:monospace;font-weight:700;}
.ww-val.force{color:#e07050;}.ww-val.body{color:#5090d0;}.ww-val.spirit{color:var(--purple);}
.ww-val.insight{color:var(--jade);}.ww-val.luck{color:var(--gold);}
.ww-bar{width:100%;height:2px;background:rgba(255,255,255,0.06);border-radius:1px;overflow:hidden;}
.ww-fill{height:100%;border-radius:1px;}
.sec{font-size:.65em;font-weight:700;letter-spacing:.15em;color:var(--dim);
  margin:14px 0 7px;display:flex;align-items:center;gap:7px;}
.sec::before{content:'';display:inline-block;width:3px;height:10px;border-radius:2px;
  background:var(--gold);box-shadow:0 0 5px var(--gold);}
.sec.green::before{background:var(--jade);box-shadow:0 0 5px var(--jade);}
.sec.purple::before{background:var(--purple);box-shadow:0 0 5px var(--purple);}
.sec.red::before{background:var(--crimson);box-shadow:0 0 5px var(--crimson);}
.txt{background:rgba(0,0,0,0.25);padding:11px 13px;border-radius:7px;
  font-size:.84em;line-height:1.7;color:#c8bcb0;margin-bottom:8px;white-space:pre-wrap;}
.txt.gold-border{border-left:2px solid rgba(200,168,75,0.4);padding-left:14px;}
.txt.jade-border{border-left:2px solid rgba(78,207,154,0.4);padding-left:14px;}
.txt.purple-border{border-left:2px solid rgba(155,114,207,0.4);padding-left:14px;}
.txt.red-border{border-left:2px solid rgba(212,90,90,0.3);padding-left:14px;}
.dual-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;}
.dual-item{padding:10px 12px;border-radius:7px;background:rgba(0,0,0,0.2);}
.dual-dir{font-size:.6em;letter-spacing:.08em;margin-bottom:5px;}
.dual-dir.good{color:var(--jade);}
.dual-dir.evil{color:var(--crimson);}
.dual-txt{font-size:.8em;color:#b8b0a8;line-height:1.6;}
.skill-row{display:flex;align-items:center;gap:10px;padding:10px 13px;
  background:rgba(155,114,207,0.06);border:1px solid rgba(155,114,207,0.15);
  border-radius:7px;margin-bottom:8px;}
.skill-name{font-size:.9em;font-weight:700;color:var(--purple);
  text-shadow:0 0 8px rgba(155,114,207,0.4);white-space:nowrap;}
.skill-sep{color:var(--dim);}
.skill-desc{font-size:.78em;color:#b0a8c0;line-height:1.5;}
.nai-block{background:rgba(0,0,0,0.3);border:1px solid rgba(155,114,207,0.2);
  border-radius:7px;padding:10px 12px;font-family:monospace;font-size:.74em;
  line-height:1.6;color:#a0a8c0;word-break:break-all;white-space:pre-wrap;margin-bottom:7px;}
.nai-btn{display:block;width:100%;padding:8px;text-align:center;
  cursor:pointer;border-radius:6px;font-size:.72em;font-weight:700;
  letter-spacing:1px;transition:.25s;user-select:none;
  border:1px solid rgba(155,114,207,0.4);color:var(--purple);
  background:rgba(155,114,207,0.05);}
.nai-btn:hover{background:rgba(155,114,207,0.15);transform:translateY(-1px);}
.btns{display:flex;gap:10px;margin-top:16px;}
.btn{flex:1;padding:11px 8px;text-align:center;cursor:pointer;
  border-radius:7px;font-weight:700;font-size:.8em;transition:.25s;user-select:none;}
.btn-ok{border:1px solid rgba(78,207,154,0.45);color:var(--jade);
  background:rgba(78,207,154,0.05);}
.btn-ok:hover{background:rgba(78,207,154,0.12);transform:translateY(-1px);}
.btn-no{border:1px solid rgba(212,90,90,0.4);color:var(--crimson);
  background:rgba(212,90,90,0.05);}
.btn-no:hover{background:rgba(212,90,90,0.12);transform:translateY(-1px);}
.btn.saving{opacity:.6;cursor:wait;}
.notice{margin-top:8px;padding:7px 12px;border-radius:6px;font-size:.7em;
  text-align:center;border:1px solid;transition:.3s;}
.notice.ok{border-color:rgba(78,207,154,0.4);color:var(--jade);background:rgba(78,207,154,0.05);}
.notice.err{border-color:rgba(212,90,90,0.4);color:var(--crimson);background:rgba(212,90,90,0.05);}
.notice.info{border-color:rgba(200,168,75,0.3);color:var(--gold);background:rgba(200,168,75,0.04);}
.err-box{text-align:center;padding:20px;color:var(--crimson);font-family:monospace;}
/* =======================================
   ====== 移动端增强自适应适配 ======
   ======================================= */
@media(max-width:600px){
  .card{padding:14px 12px;}

  /* 1. 头部标题允许上下折行，防止重叠 */
  .hdr{flex-direction:column; align-items:flex-start; gap:6px;} 

  /* 2. 基础信息降级为2列 */
  .meta-grid{grid-template-columns:repeat(2,1fr);}

  /* 3. 五维图放弃同行硬挤，改为 3+2 的网格换行 */
  .wuwei-row{display:grid; grid-template-columns:repeat(3,1fr); gap:6px;}
  .ww-item{padding:6px 4px;}

  /* 4. 善恶面降级为单列 */
  .dual-row{grid-template-columns:1fr;}

  /* 5. 绝技栏改为上下折行，允许文字换行，隐藏无用的分隔符 */
  .skill-row{flex-direction:column; align-items:flex-start; gap:4px; padding:10px;}
  .skill-name{white-space:normal; line-height:1.4;}
  .skill-sep{display:none;}

  .txt{font-size:.8em;}

  /* 6. 底部操作按钮改为上下堆叠，防止文字长短不一导致排版畸形 */
  .btns{flex-direction:column; gap:8px;} 
  .btn{padding:12px 8px;}
}

/* 极限窄屏设备 (如 iPhone SE) 特化 */
@media(max-width:380px){
  .meta-grid{grid-template-columns:1fr;} /* 姓名等基础信息降级为单列 */
  .wuwei-row{grid-template-columns:repeat(2,1fr);} /* 五维图降级为 2+2+1 */
}
}
</style>
</head>
<body>
<div class="vue-root"></div>
<pre class="raw-src" style="display:none">$1</pre>
<script>
(function(){
  var wrap=document.currentScript.parentElement;
  var root=wrap.querySelector('.vue-root');
  var src=wrap.querySelector('.raw-src');

  var FIELDS=['姓名','性别','年龄','灵根品阶','灵根属性','修为','血量上限',
    '五维','善恶值','外貌','穿着','背景','性格底色','性格主色调',
    '善面底色','恶面底色','当前表现',
    '忠诚触点','入门关系','第一面','第二面',
    '绝技名称','绝技简述','novelai_tags'];

  function parseCard(text){
    var obj={};
    FIELDS.forEach(function(f){
      var esc=f.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      var re=new RegExp('\\[\\s*'+esc+'\\s*[|:：]\\s*([\\s\\S]+?)\\s*\\](?=\\s*(?:\\[|$))','i');
      var m=re.exec(text);
      if(m) obj[f]=m[1].trim();
    });
    return obj;
  }

  function parseWuwei(str){
    if(!str) return {};
    var res={};
    var pairs=str.match(/[力体灵悟气][量质力性运][:：]\d+/g)||[];
    pairs.forEach(function(p){
      var parts=p.split(/[:：]/);
      res[parts[0]]=parseInt(parts[1])||0;
    });
    return res;
  }

  function parseHpMax(str){
    if(!str) return 0;
    var m=String(str).match(/(\d+)/);
    return m?parseInt(m[1]):0;
  }

  function getTH(){return window.TavernHelper||window.parent&&window.parent.TavernHelper||null;}

  async function saveToWorldbook(name,rawText){
    var th=getTH();
    if(!th||typeof th.createWorldbookEntries!=='function')
      throw new Error('未检测到 TavernHelper API');
    var bookName=null;
    if(typeof th.getChatWorldbookName==='function')
      try{bookName=await th.getChatWorldbookName('current');}catch(e){}
    if(!bookName&&typeof th.getOrCreateChatWorldbook==='function'){
      var stamp=new Date().toISOString().slice(0,10);
      bookName=await th.getOrCreateChatWorldbook('current','宗门弟子档案-'+stamp);
    }
    if(!bookName) throw new Error('无法获取聊天世界书');
    var entry={
      name:name,enabled:true,
      strategy:{type:'selective',keys:[name.charAt(0)]},
      position:{type:'after_character_definition',order:150},
      content:rawText
    };
    await th.createWorldbookEntries(bookName,[entry]);
  }

  var Vue3=Vue;
  Vue3.createApp({
    setup:function(){
      var data=Vue3.ref({});
      var rawText=Vue3.ref('');
      var ww=Vue3.ref({});
      var hpMax=Vue3.ref(0);
      var okTxt=Vue3.ref(''); var noTxt=Vue3.ref(''); var naiTxt=Vue3.ref('');
      var saving=Vue3.ref(false);
      var noticeMsg=Vue3.ref(''); var noticeType=Vue3.ref('info');

      Vue3.onMounted(function(){
        rawText.value=src?src.textContent:'';
        data.value=parseCard(rawText.value);
        ww.value=parseWuwei(data.value['五维']);
        hpMax.value=parseHpMax(data.value['血量上限']);
      });

      function fillTA(text){
        try{
          var ta=window.parent.document.querySelector('#send_textarea,textarea#chat_input');
          if(ta){var c=ta.value;ta.value=c?c+'\n'+text:text;ta.dispatchEvent(new Event('input',{bubbles:true}));ta.focus();return true;}
        }catch(e){}
        return false;
      }
      function fbCopy(t,cb){
        var el=document.createElement('textarea');el.value=t;document.body.appendChild(el);el.select();
        try{document.execCommand('copy');cb();}catch(e){}document.body.removeChild(el);
      }
      function showNotice(msg,type,dur){
        noticeMsg.value=msg;noticeType.value=type||'info';
        if(dur!==0)setTimeout(function(){noticeMsg.value='';},dur||4000);
      }

      async function doAction(isOk){
        if(saving.value)return;
        var name=data.value['姓名']||'该弟子';
        var text=isOk?('我批准接纳 '+name+' 入宗。'):('我婉拒了 '+name+'，不予收徒。');
        var ok=fillTA(text);
        var fb=ok?'[ 已填入输入框 ]':'[ 已复制指令 ]';
        if(isOk){
          okTxt.value=fb;setTimeout(function(){okTxt.value='';},2000);
          saving.value=true;
          showNotice('⏳ 写入聊天世界书...','info',0);
          try{
            await saveToWorldbook(name,rawText.value);
            showNotice('✓ 已存档「'+name+'」弟子档案','ok');
          }catch(e){showNotice('⚠ 存档失败：'+(e&&e.message||e),'err',6000);}
          saving.value=false;
        }else{
          noTxt.value=fb;setTimeout(function(){noTxt.value='';},2000);
        }
        if(!ok)fbCopy(text,function(){});
      }

      function copyNai(){
        var tags=data.value['novelai_tags']||'';
        if(!tags)return;
        var cb=function(){naiTxt.value='[ Copied! ]';setTimeout(function(){naiTxt.value='';},2000);};
        if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(tags).then(cb).catch(function(){fbCopy(tags,cb);});
        else fbCopy(tags,cb);
      }

      var wwCombatMax=Vue3.computed(function(){
        var m=Math.max(ww.value['力量']||0,ww.value['体质']||0,ww.value['灵力']||0);
        if(m<=0)return 100;
        var raw=Math.ceil(m*1.5/100)*100;
        return Math.max(100,raw);
      });
      function wwPct(val,isCombat){
        var max=isCombat?wwCombatMax.value:100;
        return max>0?Math.min(100,Math.round(val/max*100)):0;
      }

      return{data,ww,hpMax,wwCombatMax,okTxt,noTxt,naiTxt,saving,noticeMsg,noticeType,doAction,copyNai,wwPct};
    },
    template:`
      <div v-if="!data['姓名']" class="err-box">[ 档案解析失败：未检测到弟子姓名字段 ]</div>
      <div v-else class="card">
        <div class="hdr">
          <span class="hdr-title">散修来访 · 弟子档案</span>
          <span class="hdr-status">● 等待掌门裁决</span>
        </div>

        <!-- 主信息第1行：姓名/灵根品阶/灵根属性/修为 -->
        <div class="meta-grid">
          <div class="meta-item"><div class="meta-label">姓名</div>
            <div class="meta-val gold">{{ data['姓名'] }}</div></div>
          <div class="meta-item"><div class="meta-label">灵根品阶</div>
            <div class="meta-val" :class="'root-'+data['灵根品阶']">{{ data['灵根品阶'] }}</div></div>
          <div class="meta-item"><div class="meta-label">灵根属性</div>
            <div class="meta-val cyan">{{ data['灵根属性'] || '—' }}</div></div>
          <div class="meta-item"><div class="meta-label">修为</div>
            <div class="meta-val jade">{{ data['修为'] || '—' }}</div></div>
        </div>

        <!-- 主信息第2行：性别年龄/血量上限/善恶值/入门关系 -->
        <div class="meta-grid" style="margin-bottom:14px">
          <div class="meta-item"><div class="meta-label">性别 / 年龄</div>
            <div class="meta-val">{{ data['性别'] }} / {{ data['年龄'] }}岁</div></div>
          <div class="meta-item"><div class="meta-label">血量上限</div>
            <div class="meta-val jade">{{ data['血量上限'] }}</div></div>
          <div class="meta-item"><div class="meta-label">善恶值</div>
            <div class="meta-val" :style="{color:Number(data['善恶值'])>=0?'var(--jade)':'var(--crimson)'}">{{ data['善恶值'] }}</div></div>
          <div class="meta-item"><div class="meta-label">入门关系</div>
            <div class="meta-val" style="font-size:.75em;color:var(--silver)">{{ data['入门关系'] }}</div></div>
        </div>

        <!-- 五维 -->
        <div class="sec">五维属性</div>
        <div class="wuwei-row">
          <div class="ww-item">
            <div class="ww-label">力量</div>
            <div class="ww-val force">{{ ww['力量']||0 }}</div>
            <div class="ww-bar"><div class="ww-fill" style="background:#e07050;" :style="{width:wwPct(ww['力量']||0,true)+'%'}"></div></div>
          </div>
          <div class="ww-item">
            <div class="ww-label">体质</div>
            <div class="ww-val body">{{ ww['体质']||0 }}</div>
            <div class="ww-bar"><div class="ww-fill" style="background:#5090d0;" :style="{width:wwPct(ww['体质']||0,true)+'%'}"></div></div>
          </div>
          <div class="ww-item">
            <div class="ww-label">灵力</div>
            <div class="ww-val spirit">{{ ww['灵力']||0 }}</div>
            <div class="ww-bar"><div class="ww-fill" style="background:var(--purple);" :style="{width:wwPct(ww['灵力']||0,true)+'%'}"></div></div>
          </div>
          <div class="ww-item">
            <div class="ww-label">悟性</div>
            <div class="ww-val insight">{{ ww['悟性']||0 }}</div>
            <div class="ww-bar"><div class="ww-fill" style="background:var(--jade);" :style="{width:wwPct(ww['悟性']||0,false)+'%'}"></div></div>
          </div>
          <div class="ww-item">
            <div class="ww-label">气运</div>
            <div class="ww-val luck">{{ ww['气运']||0 }}</div>
            <div class="ww-bar"><div class="ww-fill" style="background:var(--gold);" :style="{width:wwPct(ww['气运']||0,false)+'%'}"></div></div>
          </div>
        </div>

        <!-- 外貌与穿着 -->
        <div class="sec">外貌记录</div>
        <div class="txt gold-border">{{ data['外貌'] }}</div>
        <div class="txt" style="font-size:.78em;color:#9090a0;">{{ data['穿着'] }}</div>

        <!-- 背景 -->
        <div class="sec green">背景档案</div>
        <div class="txt jade-border">{{ data['背景'] }}</div>

        <!-- 性格 -->
        <div class="sec">性格分析</div>
        <div class="txt gold-border">
          <span style="font-size:.66em;color:var(--gold);display:block;margin-bottom:4px">核心底色</span>
          {{ data['性格底色'] }}
          <div style="height:8px"></div>
          <span style="font-size:.66em;color:var(--dim);display:block;margin-bottom:4px">表层主色调</span>
          <span style="color:var(--silver)">{{ data['性格主色调'] }}</span>
        </div>

        <!-- 善恶面 -->
        <div class="sec purple">善恶归途</div>
        <div class="dual-row">
          <div class="dual-item" style="border:1px solid rgba(78,207,154,0.15);">
            <div class="dual-dir good">▲ 善之归途</div>
            <div class="dual-txt">{{ data['善面底色'] }}</div>
          </div>
          <div class="dual-item" style="border:1px solid rgba(212,90,90,0.15);">
            <div class="dual-dir evil">▼ 恶之深渊</div>
            <div class="dual-txt">{{ data['恶面底色'] }}</div>
          </div>
        </div>

        <!-- 当前表现（独立行） -->
        <div v-if="data['当前表现']" style="margin-bottom:8px;padding:10px 13px;border-radius:7px;background:rgba(0,0,0,0.2);border-left:2px solid rgba(200,168,75,0.3);">
          <div style="font-size:.6em;color:var(--dim);letter-spacing:.08em;margin-bottom:5px;">当前表现</div>
          <div style="font-size:.82em;color:#b8b0a8;line-height:1.6;">{{ data['当前表现'] }}</div>
        </div>
        <div v-else style="display:none">
        </div>

        <!-- 忠诚触点 -->
        <div class="sec red">忠诚触点</div>
        <div class="txt red-border" style="font-size:.8em;color:#b8a8a8">{{ data['忠诚触点'] }}</div>

        <!-- 初见/私下 -->
        <div class="sec">行为评估</div>
        <div class="txt gold-border">
          <span style="font-size:.66em;color:var(--gold);display:block;margin-bottom:4px">初见掌门</span>
          {{ data['第一面'] }}
          <div style="height:8px"></div>
          <span style="font-size:.66em;color:var(--dim);display:block;margin-bottom:4px">私下状态</span>
          <span style="color:#a8a098">{{ data['第二面'] }}</span>
        </div>

        <!-- 绝技 -->
        <div class="sec purple">专属绝技</div>
        <div class="skill-row">
          <span class="skill-name">✦ {{ data['绝技名称'] }}</span>
          <span class="skill-sep">·</span>
          <span class="skill-desc">{{ data['绝技简述'] }}</span>
        </div>

        <!-- NAI -->
        <div class="sec">NovelAI Tags</div>
        <div v-if="data['novelai_tags']" class="nai-block">{{ data['novelai_tags'] }}</div>
        <div v-else class="nai-block" style="color:#444;font-style:italic">[ 无标签数据 ]</div>
        <div class="nai-btn" @click="copyNai">
          <span v-if="naiTxt">{{ naiTxt }}</span><span v-else>⧉ 复制 NAI Tags</span>
        </div>

        <!-- 按钮 -->
        <div class="btns">
          <div class="btn btn-ok" :class="{saving}" @click="doAction(true)">
            <span v-if="okTxt">{{ okTxt }}</span>
            <span v-else-if="saving">⏳ 存档中...</span>
            <span v-else>✓ 收入门下
              <span style="font-size:.72em;opacity:.6;display:block;margin-top:2px">将同步存档到聊天世界书</span>
            </span>
          </div>
          <div class="btn btn-no" @click="doAction(false)">
            <span v-if="noTxt">{{ noTxt }}</span><span v-else>✗ 婉拒离宗</span>
          </div>
        </div>
        <div v-if="noticeMsg" class="notice" :class="noticeType">{{ noticeMsg }}</div>
      </div>
    `
  }).mount(root);
})();
</script>
</body>
