<div id="output"></div>
<script>
(function(){
  var raw='<tournament_panel>'+`$1`+'</tournament_panel>';

  function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

  /* 从raw中提取字段值，支持 字段:[值] 和 字段:值 两种格式 */
  function get(f){
    var re=new RegExp(f+'\\s*[：:]\\s*\\[([^\\]]+)\\]','i');
    var m=re.exec(raw);
    if(m) return m[1].trim();
    var re2=new RegExp('\\|\\s*'+f+'\\s*[：:]\\s*([^|\\[\\]\\n]+)','i');
    var m2=re2.exec(raw);
    return m2?m2[1].trim():'';
  }

  /* 解析上阵弟子行（含HP的本宗行） */
  var ourLines=raw.split('\n').map(function(l){return l.trim();}).filter(function(l){
    return l.startsWith('|')&&/HP[：:]/i.test(l)&&!/对手[：:]/i.test(l)&&!/上阵弟子[：:]/i.test(l);
  });
  /* 解析对手行 */
  var oppLines=raw.split('\n').map(function(l){return l.trim();}).filter(function(l){
    return l.startsWith('|')&&/对手[：:]/i.test(l);
  });

  function parseUnit(line){
    /* 对手行 */
    var oppM=line.match(/对手[：:]\[([^\]]+)\]/i)||line.match(/对手[：:]\s*([^\s\[|HP][^\s|]*)/i);
    if(oppM){
      var hp=line.match(/HP[：:]\[([^\]]+)\]/i)||line.match(/HP[：:]\s*([\d\/]+)/i);
      var atk=line.match(/ATK[：:]\[([^\]]+)\]/i)||line.match(/ATK[：:]\s*(\d+)/i);
      return{name:oppM[1].trim(),hp:hp?hp[1].trim():'',atk:atk?atk[1].trim():''};
    }
    /* 本宗行：名字在第一个[...]或第一个字段前 */
    var nm=line.match(/\]\s+([^\[\]|\s][^\s|[]*)/)||line.match(/弟子[AB]?[：:]\s*([^\s,，HP|]+)/i);
    if(!nm){
      /* 尝试直接从|后取第一个非字段词 */
      var bare=line.replace(/^\s*\|/,'').split('|')[0].trim();
      var bmatch=bare.match(/^([^\s:：\[]+)/);
      if(bmatch) nm=[null,bmatch[1]];
    }
    var hp=line.match(/HP[：:]\[([^\]]+)\]/i)||line.match(/HP[：:]\s*([\d\/]+)/i);
    var atk=line.match(/ATK[：:]\[([^\]]+)\]/i)||line.match(/ATK[：:]\s*(\d+)/i);
    return{name:nm?nm[1].trim():'',hp:hp?hp[1].trim():'',atk:atk?atk[1].trim():''};
  }

  function hpPct(s){
    var m=String(s).match(/(\d+)\/(\d+)/);
    return m?Math.min(100,Math.round(parseInt(m[1])/parseInt(m[2])*100)):100;
  }

  var session=get('届次'),rank=get('阶位'),status=get('状态');
  var stage=get('赛程'),curRound=get('当前轮');
  var result=get('结果'),prestigeRaw=get('本轮声望');
  /* 去掉括号说明文字，只保留如 +150 的数值部分 */
  var prestige=prestigeRaw.replace(/[（(][^）)]*[）)]/g,'').trim();
  var record=get('累计战绩'),curRank=get('当前名次');

  var isActive=status.indexOf('进行')>=0;
  var isWin=result.indexOf('胜')>=0,isLose=result.indexOf('负')>=0;
  var isPending=!result||result.indexOf('待定')>=0||result==='';

  var stages=['预选赛','四强赛','决赛'];
  var stageIdx=stages.indexOf(stage);

  var html='<div class="card">';

  /* 标题栏 */
  html+='<div class="hdr"><span class="title">宗门大比</span><div class="meta">';
  if(session) html+='<span class="tag tag-dim">'+esc(session)+'</span>';
  if(rank) html+='<span class="tag tag-rank">'+esc(rank)+'</span>';
  html+='<span class="tag '+(isActive?'tag-on':'tag-off')+'">'+esc(status||'未开始')+'</span>';
  html+='</div></div>';

  /* 阶段进度条 */
  html+='<div class="stage-bar">';
  stages.forEach(function(s,i){
    var cls='st'+(i<stageIdx?' done':i===stageIdx?' cur':'');
    html+='<div class="'+cls+'">'+esc(s)+(i===stageIdx&&curRound?' · '+esc(curRound):'')+'</div>';
  });
  html+='</div>';

  /* 对阵区 */
  if(ourLines.length||oppLines.length){
    html+='<div class="match">';
    html+='<div class="team our"><div class="team-label">⚔ 本宗</div>';
    ourLines.forEach(function(l){
      var u=parseUnit(l);
      var pct=u.hp?hpPct(u.hp):100;
      html+='<div class="fighter"><span class="fname">'+esc(u.name||'—')+'</span>'+(u.atk?'<span class="fatk">ATK '+esc(u.atk)+'</span>':'')+'</div>';
      if(u.hp) html+='<div class="hpb"><div class="hpa" style="width:'+pct+'%"></div></div><div class="hpt">HP '+esc(u.hp)+'</div>';
    });
    html+='</div>';
    html+='<div class="vs">VS</div>';
    html+='<div class="team opp"><div class="team-label">💀 对手</div>';
    oppLines.forEach(function(l){
      var u=parseUnit(l);
      var pct=u.hp?hpPct(u.hp):100;
      html+='<div class="fighter"><span class="fname">'+esc(u.name||'—')+'</span>'+(u.atk?'<span class="fatk">ATK '+esc(u.atk)+'</span>':'')+'</div>';
      if(u.hp) html+='<div class="hpb"><div class="hpo" style="width:'+pct+'%"></div></div><div class="hpt">HP '+esc(u.hp)+'</div>';
    });
    html+='</div></div>';
  }

  /* 结果栏：仅在有明确胜负时显示 */
  if(!isPending){
    var rCls=isWin?'rwin':isLose?'rlose':'rpend';
    var rIcon=isWin?'🏆':isLose?'💔':'⚔';
    html+='<div class="rbar '+rCls+'">';
    html+=rIcon+' '+esc(result);
    if(prestige&&prestige!='0'&&prestige!='+0') html+=' · 声望 '+esc(prestige);
    html+='</div>';
  }

  /* 战绩标签：只显示累计战绩和累计声望，不显示名次/进行中等标签 */
  html+='<div class="chips">';
  if(record) html+='<span class="chip crec">'+esc(record)+'</span>';
  var totalPrestige=get('累计声望');
  if(totalPrestige&&totalPrestige!='0'&&totalPrestige!='+0') html+='<span class="chip cpres">声望 '+esc(totalPrestige)+'</span>';
  html+='</div>';

  /* 按钮 */
  html+='<div class="btns">';
  html+='<div class="btn bfight" onclick="sendCmd(true)">⚔ 开始本场对战</div>';
  html+='<div class="btn brecall" onclick="sendCmd(false)">↩ 申请弃权退出</div>';
  html+='</div>';

  html+='</div>';
  document.getElementById('output').innerHTML=html;

  window.sendCmd=function(isFight){
    var stageStr=stage?(stage+(curRound?' '+curRound:'')):'对战';
    var cmd=isFight
      ?('宣告【'+session+'·'+stageStr+'】本场开始对战！')
      :('我方申请弃权，退出本届大比。');
    try{
      var ta=window.parent.document.querySelector('#send_textarea,textarea#chat_input');
      if(ta){var v=ta.value;ta.value=v?v+'\n'+cmd:cmd;
        ta.dispatchEvent(new Event('input',{bubbles:true}));ta.focus();return;}
    }catch(e){}
    try{navigator.clipboard.writeText(cmd);}catch(e2){}
  };
})();
</script>
</body>
</html>
