(function(){
  var raw = document.getElementById('raw').textContent;
  var root = document.getElementById('root');

  function get(f) {
    // 方括号格式：[弟子|xxx]
    var re = new RegExp('\\[\\s*' + f + '\\s*[|:：]\\s*([^\\]]+)\\]', 'i');
    var m = re.exec(raw);
    if (m) return m[1].trim();
    // 冒号格式：触发弟子：xxx / 事件描述：xxx
    var re2 = new RegExp('(?:触发)?' + f + '(?:描述)?[\\s]*[|:：]+\\s*([^\n\r<]+)', 'i');
    var m2 = re2.exec(raw);
    if (m2) return m2[1].trim();
    // 单行兜底：第一行「名字：内容」
    if (f === '弟子') {
      var sl = raw.trim().split(/[\n\r]/)[0];
      var ci = sl.search(/[:：]/);
      if (ci > 0) return sl.slice(0, ci).trim();
    }
    if (f === '事件') {
      var sl2 = raw.trim();
      var ci2 = sl2.search(/[:：]/);
      if (ci2 > 0) return sl2.slice(ci2 + 1).trim().split(/[\n\r]/)[0];
    }
    return '';
  }

  var name = get('弟子');
  var ev   = get('事件');

  root.innerHTML =
    '<div class="le-hdr">' +
      '<span class="le-icon">❤</span>' +
      '<span class="le-title">忠诚度事件</span>' +
      (name ? '<span class="le-name">' + name + '</span>' : '') +
    '</div>' +
    (ev
      ? '<div class="le-event">' + ev + '</div>'
      : '<div class="le-event" style="color:rgba(255,255,255,0.3);font-style:italic;">（暂无事件描述）</div>');
})();
</script>
</body>
