.unit-card.ally::before  {background:var(--jade);   box-shadow:0 0 8px var(--jade);}
.unit-card.guest::before {background:var(--cyan);   box-shadow:0 0 8px var(--cyan);}
.unit-card.enemy::before {background:var(--crimson);box-shadow:0 0 8px var(--crimson);}
.unit-card.dead{opacity:.4;filter:grayscale(.7);}
.unit-card.dead::before{background:#444;box-shadow:none;}

.unit-name-row{
  display:flex;align-items:center;justify-content:space-between;gap:6px;
  flex-wrap:wrap;
}
.unit-name{
  font-weight:700;font-size:.9em;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:120px;
}
.unit-badge{
  font-size:.6em;padding:1px 7px;border-radius:10px;font-weight:700;
  letter-spacing:.5px;flex-shrink:0;
}
.badge-normal  {background:rgba(78,207,154,0.12);color:var(--jade);  border:1px solid rgba(78,207,154,0.3);}
.badge-injured {background:rgba(200,168,75,0.12); color:var(--gold);  border:1px solid rgba(200,168,75,0.3);}
.badge-critical{background:rgba(212,90,90,0.15);  color:var(--crimson);border:1px solid rgba(212,90,90,0.4);
                animation:badge-pulse 1.2s infinite ease-in-out;}
.badge-dead    {background:rgba(80,80,80,0.2);     color:#555;         border:1px solid #444;}
@keyframes badge-pulse{
  0%,100%{box-shadow:0 0 4px rgba(212,90,90,0.4);}
  50%    {box-shadow:0 0 10px rgba(212,90,90,0.8);}
}

/* ── HP/攻击行 ── */
.bar-row{
  display:flex;align-items:center;gap:6px;
  font-family:monospace;font-size:.78em;
}
.bar-label{color:var(--dim);width:22px;flex-shrink:0;font-size:.9em;}
.bar-track{
  flex:1;height:4px;background:rgba(255,255,255,0.06);
  border-radius:3px;overflow:hidden;
}
.bar-fill{height:100%;border-radius:3px;transition:width .5s cubic-bezier(.4,0,.2,1);}
.bar-ally  {background:linear-gradient(90deg,#8b0000,var(--jade)); box-shadow:0 0 5px var(--jade);}
.bar-guest {background:linear-gradient(90deg,#003a55,var(--cyan)); box-shadow:0 0 5px var(--cyan);}
.bar-enemy {background:linear-gradient(90deg,#5a0000,var(--crimson));box-shadow:0 0 5px var(--crimson);}
.bar-val{color:#fff;width:60px;text-align:right;flex-shrink:0;font-size:.85em;}
.bar-val.crit{color:var(--crimson);animation:text-crit 1s infinite;}
@keyframes text-crit{
  0%,100%{text-shadow:0 0 4px var(--crimson);}
  50%    {text-shadow:0 0 10px var(--crimson);}
}
.atk-line{
  font-family:monospace;font-size:.74em;color:var(--dim);
  display:flex;align-items:center;gap:5px;
}
.atk-val{color:var(--gold);font-weight:700;text-shadow:0 0 5px rgba(200,168,75,0.4);}

/* ── 攻击结算卡片 ── */
.attack-card{
  background:rgba(16,14,24,0.85);border:1px solid rgba(200,168,75,0.2);
  border-radius:8px;padding:11px 14px;
  display:flex;flex-direction:column;gap:8px;
  position:relative;overflow:hidden;
}
.attack-card::before{
  content:'';position:absolute;top:0;left:0;right:0;height:1px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
}
.atk-header{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:.88em;
}
.atk-from,.atk-to{font-weight:700;}
.atk-from.ally  {color:var(--jade);  text-shadow:0 0 6px rgba(78,207,154,0.4);}
.atk-from.guest {color:var(--cyan);  text-shadow:0 0 6px rgba(92,200,212,0.4);}
.atk-from.enemy {color:var(--crimson);text-shadow:0 0 6px rgba(212,90,90,0.4);}
.atk-to.ally    {color:var(--jade);}
.atk-to.enemy   {color:var(--crimson);}
.atk-arrow{color:var(--dim);font-weight:700;font-size:1.1em;padding:0 2px;}
.divider{height:1px;background:linear-gradient(90deg,transparent,rgba(200,168,75,0.15),transparent);}

.dice-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-family:monospace;font-size:.82em;}
.dice-label{color:var(--dim);font-size:.85em;}
.dice-badge{
  display:inline-flex;align-items:center;gap:5px;
  padding:3px 10px;border-radius:6px;font-weight:700;border:1px solid;
}
.dice-badge.great  {background:rgba(200,168,75,0.15); border-color:var(--gold);   color:var(--gold);
                    animation:crit-glow .8s infinite alternate;}
.dice-badge.hit    {background:rgba(92,200,212,0.1);  border-color:var(--cyan);   color:var(--cyan);}
.dice-badge.graze  {background:rgba(160,180,200,0.08);border-color:var(--dim);    color:var(--silver);}
.dice-badge.miss   {background:rgba(50,50,60,0.2);    border-color:#444;          color:#555;}
@keyframes crit-glow{
  from{box-shadow:0 0 6px rgba(200,168,75,0.3);}
  to  {box-shadow:0 0 18px rgba(200,168,75,0.7),0 0 4px #fff;}
}
/* 绝技特效 */
.skill-wrap{border-color:rgba(155,114,207,0.35)!important;}
.skill-wrap::before{background:linear-gradient(90deg,transparent,rgba(155,114,207,0.7),rgba(200,168,75,0.6),rgba(155,114,207,0.7),transparent)!important;}
.skill-card{border-color:rgba(155,114,207,0.3)!important;animation:skill-shimmer 2s infinite;}
@keyframes skill-shimmer{
  0%,100%{box-shadow:0 0 8px rgba(155,114,207,0.2),inset 0 0 20px rgba(155,114,207,0.03);}
  50%    {box-shadow:0 0 20px rgba(155,114,207,0.5),inset 0 0 30px rgba(155,114,207,0.07);}
}
.skill-banner{
  display:flex;align-items:center;justify-content:center;gap:10px;
  padding:7px 14px;margin:4px 0;
  background:linear-gradient(90deg,transparent,rgba(155,114,207,0.15),rgba(155,114,207,0.2),rgba(155,114,207,0.15),transparent);
  border-top:1px solid rgba(155,114,207,0.2);border-bottom:1px solid rgba(155,114,207,0.2);
  animation:skill-banner-glow 1.5s infinite alternate;
}
@keyframes skill-banner-glow{
  from{filter:brightness(1);}
  to  {filter:brightness(1.3);}
}
.skill-banner-name{
  font-size:.95em;font-weight:800;color:var(--purple);
  letter-spacing:.25em;text-shadow:0 0 12px rgba(155,114,207,0.8),0 0 4px rgba(155,114,207,0.4);
}
.skill-rune{font-size:.8em;color:rgba(155,114,207,0.6);animation:skill-rune-spin 3s linear infinite;display:inline-block;}
@keyframes skill-rune-spin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}
.skill-tag{
  display:inline-flex;align-items:center;gap:5px;
  padding:2px 8px;border-radius:4px;font-size:.73em;font-weight:700;
  background:rgba(155,114,207,0.15);border:1px solid rgba(155,114,207,0.4);color:var(--purple);
  text-shadow:0 0 6px rgba(155,114,207,0.4);
}

.dmg-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-family:monospace;font-size:.82em;}
.dmg-formula{color:var(--dim);font-size:.85em;}
.dmg-box{
  display:inline-flex;align-items:center;gap:6px;padding:4px 12px;
  border-radius:6px;font-weight:800;font-size:1.05em;
}
.dmg-box.crit  {background:rgba(200,168,75,0.15); border:1px solid var(--gold);   color:var(--gold);}
.dmg-box.normal{background:rgba(212,90,90,0.12);  border:1px solid rgba(212,90,90,0.35); color:var(--crimson);}
.dmg-box.heal  {background:rgba(78,207,154,0.1);  border:1px solid rgba(78,207,154,0.3); color:var(--jade);}

.hp-row{display:flex;align-items:center;gap:8px;font-family:monospace;font-size:.82em;flex-wrap:wrap;}
.hp-old{color:var(--dim);}
.hp-arrow{color:#444;font-weight:700;}
.hp-new{font-weight:700;}
.hp-new.safe{color:var(--jade);}
.hp-new.warn{color:var(--gold);}
.hp-new.crit{color:var(--crimson);animation:text-crit 1s infinite;}
.hp-new.dead{color:#555;}
.death-tag{
  display:inline-flex;align-items:center;gap:4px;
  padding:2px 8px;border-radius:4px;font-size:.73em;font-weight:700;
  background:rgba(100,0,0,0.2);border:1px solid rgba(212,90,90,0.5);color:var(--crimson);
}

@media(max-width:600px){
  .combat-wrap{padding:10px;gap:9px;}
  .combat-title-text{font-size:.78em;letter-spacing:.08em;}
  .unit-grid{grid-template-columns:1fr;}
  .unit-card{padding:8px 10px;}
  .atk-header{font-size:.78em;}
  .dice-row,.dmg-row,.hp-row{font-size:.74em;}
}
</style>
</head>
<body>
<div id="output"></div>
<script>
(function(){
  var raw='<battle_panel>'+`$1`+'</battle_panel>';

  function esc(s){
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function parseHp(s){
    if(!s) return null;
    var m=String(s).match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)/);
    if(m) return {cur:parseFloat(m[1]),max:parseFloat(m[2])};
    var n=parseFloat(s);
    return isNaN(n)?null:{cur:n,max:n};
  }
  function hpPct(c,m){return m>0?Math.min(100,Math.max(0,c/m*100)):0;}
  function hpStatus(c,m){
    if(c<=0) return 'dead';
    var p=hpPct(c,m);
    if(p<=20) return 'critical';
    if(p<=55) return 'injured';
    return 'normal';
  }
  function badge(st){
    var map={
      normal:  ['badge-normal',  '正常'],
      injured: ['badge-injured', '受伤'],
      critical:['badge-critical','濒危'],
      dead:    ['badge-dead',    '陨落']
    };
    var i=map[st]||map.normal;
    return '<span class="unit-badge '+i[0]+'">'+i[1]+'</span>';
  }
  function barHtml(c,m,cls){
    var pct=hpPct(c,m).toFixed(1);
    var dead=c<=0;
    return '<div class="bar-row">'
      +'<span class="bar-label">HP</span>'
      +'<div class="bar-track"><div class="bar-fill '+cls+'" style="width:'+pct+'%"></div></div>'
      +'<span class="bar-val'+(dead?' crit':'')+'">'+c+'/'+m+'</span>'
      +'</div>';
  }
  function parsePipe(line){
    var obj={};
    var s=line.replace(/^\s*\|/,'').replace(/\|\s*$/,'');
    // 先按 | 分段，再对每段处理多个 key:value
    s.split('|').forEach(function(seg){
      seg=seg.trim(); if(!seg) return;
      // 用正向lookahead按「字段名:」边界拆分，支持一段内多key
      var kvRe=/([^\s:：][^:：]*)[:：]([^:：]+(?=\s+[^\s:：][^:：]*[:：]|$))/g;
      var matched=false, m;
      while((m=kvRe.exec(seg))!==null){
        matched=true;
        var k=m[1].trim(), v=m[2].trim();
        // 如果 k 含空格，前面部分可能是名字
        var sp=k.indexOf(' ');
        if(sp>0&&!obj['__name__']){
          obj['__name__']=k.slice(0,sp).trim();
          k=k.slice(sp+1).trim();
        }
        if(k) obj[k]=v;
      }
      // 如果整段没有冒号，当作名字
      if(!matched&&!obj['__name__']) obj['__name__']=seg;
    });
    return obj;
  }

  /* ══ 渲染战斗面板 ══ */
  function renderPanel(inner){
    var lines=inner.split('\n').map(function(l){return l.trim();}).filter(function(l){return /^\|/.test(l);});
    var all=lines.map(parsePipe);
    var roundNum='',sceneStr='';
    var allies=[],guests=[],enemies=[];

    all.forEach(function(d){
      if(d['回合']){roundNum=d['回合'];sceneStr=d['场景']||'';return;}
      // 优先用明确类型前缀（弟子:/队友:/敌方:）判断
      if(d['弟子']){
        d['__name__']=d['弟子'];delete d['弟子'];
        allies.push(d);
      } else if(d['队友']){
        d['__name__']=d['队友'];delete d['队友'];
        guests.push(d);
      } else if(d['敌方']){
        d['__name__']=d['敌方'];delete d['敌方'];
        enemies.push(d);
      } else {
        // 降级：兜底用关键词猜
        var text=Object.keys(d).join(' ')+' '+Object.values(d).join(' ');
        if(/队友|临时/.test(text)){guests.push(d);}
        else if(/妖兽|魔族|修士|敌方|BOSS|精英|他宗|变异|尸|兽/.test(text)){enemies.push(d);}
        else if(d['血量']||d['实际攻击力']){allies.push(d);}
      }
    });

    var html='<div class="combat-wrap">';
    // 标题
    html+='<div class="combat-title-bar">';
    html+='<div class="combat-title-left"><span class="combat-title-icon">⚔</span><span class="combat-title-text">战斗</span></div>';
    html+='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">';
    if(roundNum) html+='<span class="combat-round-badge">第 '+esc(roundNum)+' 回合</span>';
    if(sceneStr) html+='<span class="combat-scene-tag">'+esc(sceneStr)+'</span>';
    html+='</div></div>';

    // 我方弟子
    if(allies.length>0){
      html+='<div><div class="section-label ally">⚔ 参战弟子</div><div class="unit-grid">';
      allies.forEach(function(d){
        var name=d['__name__']||Object.keys(d)[0]||'?';
        var hpRaw=d['血量']||'';
    // 支持 '[旧值] → [新值]' 格式
    var hpOld=0,hpNew=0;
    var hpArrow=String(hpRaw).split('→');
    hpOld=parseInt(hpArrow[0].replace(/[\[\]]/g,'').trim())||0;
    hpNew=parseInt(hpArrow[1]?hpArrow[1].replace(/[\[\]]/g,'').trim():'0')||0;
        var atkRaw=d['实际攻击力']||d['攻击力']||'';
        var stRaw=d['状态']||'';
        var skillRaw=d['绝技']||'';
        var hp=parseHp(hpRaw);
        var st=hp?hpStatus(hp.cur,hp.max):(stRaw||'normal');
        var dead=st==='陨落'||(hp&&hp.cur<=0);
        // 解析绝技名和剩余次数，格式：「绝技名(剩余N次)」
        var skillName='',skillLeft=0;
        if(skillRaw){
          var sm=String(skillRaw).match(/^(.+?)\s*[\(（]剩余\[?(\d+)\]?次[\)）]/);
          if(sm){skillName=sm[1].trim().replace(/^\[|\]$/g,'');skillLeft=parseInt(sm[2]);}
          else{skillName=skillRaw.replace(/^\[|\]$/g,'');skillLeft=1;}
        }
        html+='<div class="unit-card ally'+(dead?' dead':'')+'">';
        html+='<div class="unit-name-row"><span class="unit-name">'+esc(name)+'</span>'+badge(dead?'dead':st)+'</div>';
        if(hp) html+=barHtml(hp.cur,hp.max,'bar-ally');
        if(atkRaw) html+='<div class="atk-line">实攻 <span class="atk-val">'+esc(atkRaw)+'</span></div>';
        if(skillName) html+='<div class="atk-line" style="margin-top:2px;">'
          +'<span style="color:'+(skillLeft>0?'var(--purple)':'#555')+';font-weight:700;">✦ '+esc(skillName)+'</span>'
          +'<span style="font-size:.78em;color:'+(skillLeft>0?'var(--text-dim)':'#444')+';margin-left:4px;">剩余'+skillLeft+'次</span>'
          +'</div>';
        html+='</div>';
      });
      html+='</div></div>';
    }

    // 临时队友
    if(guests.length>0){
      html+='<div><div class="section-label guest">🤝 临时队友</div><div class="unit-grid">';
      guests.forEach(function(d){
        var name=d['__name__']||Object.keys(d)[0]||'?';
        var hpRaw=d['血量']||d['估算血量']||'';
        var atkRaw=d['攻击力']||'';
        var hp=parseHp(hpRaw);
        var st=hp?hpStatus(hp.cur,hp.max):'normal';
        html+='<div class="unit-card guest">';
        html+='<div class="unit-name-row"><span class="unit-name">'+esc(name)+'</span>'+badge(st)+'</div>';
        if(hp) html+=barHtml(hp.cur,hp.max,'bar-guest');
        if(atkRaw) html+='<div class="atk-line">攻击 <span class="atk-val">'+esc(atkRaw)+'</span></div>';
        html+='</div>';
      });
      html+='</div></div>';
    }

    // 敌方
    if(enemies.length>0){
      html+='<div><div class="section-label enemy">💀 敌方</div><div class="unit-grid">';
      enemies.forEach(function(d){
        var name=d['__name__']||Object.keys(d)[0]||'?';
        var hpRaw=d['血量']||'';
    // 支持 '[旧值] → [新值]' 格式
    var hpOld=0,hpNew=0;
    var hpArrow=String(hpRaw).split('→');
    hpOld=parseInt(hpArrow[0].replace(/[\[\]]/g,'').trim())||0;
    hpNew=parseInt(hpArrow[1]?hpArrow[1].replace(/[\[\]]/g,'').trim():'0')||0;
        var atkRaw=d['攻击力']||'';
        var stRaw=d['状态']||'';
        var hp=parseHp(hpRaw);
        var st=hp?hpStatus(hp.cur,hp.max):(stRaw||'normal');
        var dead=st==='陨落'||(hp&&hp.cur<=0);
        html+='<div class="unit-card enemy'+(dead?' dead':'')+'">';
        html+='<div class="unit-name-row"><span class="unit-name">'+esc(name)+'</span>'+badge(dead?'dead':st)+'</div>';
        if(hp) html+=barHtml(hp.cur,hp.max,'bar-enemy');
        if(atkRaw) html+='<div class="atk-line">攻击 <span class="atk-val">'+esc(atkRaw)+'</span></div>';
        html+='</div>';
      });
      html+='</div></div>';
    }

    html+='</div>';
    return html;
  }

  /* ══ 渲染攻击结算 ══ */
  function renderAttack(inner){
    var lines=inner.split('\n').map(function(l){return l.trim();}).filter(function(l){return /^\|/.test(l);});
    var d={};
    lines.forEach(function(l){Object.assign(d,parsePipe(l));});

    // 支持 '攻方:[X] → 守方:[Y]' 单行格式
    var fromRaw=d['攻方']||'';
    var toRaw=d['守方']||'';
    if(fromRaw.indexOf('→')>=0){
      var arr=fromRaw.split('→');
      fromRaw=arr[0].replace(/[\[\]]/g,'').trim();
      toRaw=arr[1]?arr[1].replace(/守方[：:]/,'').replace(/[\[\]]/g,'').trim():toRaw;
    } else {
      fromRaw=fromRaw.replace(/[\[\]]/g,'').trim();
      toRaw=toRaw.replace(/[\[\]]/g,'').trim();
    }
    var diceRaw=d['D20骰值']||d['骰值']||'';
    var dmgRaw=d['伤害']||'';
    // 提取最终伤害值（取等号后的数字）
    var dmgFinal=0;
    var dmgEqM=String(dmgRaw).match(/=\s*(\d+)/);
    if(dmgEqM){dmgFinal=parseInt(dmgEqM[1]);}
    else{dmgFinal=parseInt(String(dmgRaw).replace(/[\[\]]/g,'').match(/(\d+)/)?.[1]||'0');}
    var hpRaw=d['血量']||'';
    // 支持 '[旧值] → [新值]' 格式
    var hpOld=0,hpNew=0;
    var hpArrow=String(hpRaw).split('→');
    hpOld=parseInt(hpArrow[0].replace(/[\[\]]/g,'').trim())||0;
    hpNew=parseInt(hpArrow[1]?hpArrow[1].replace(/[\[\]]/g,'').trim():'0')||0;
    var skillRaw=d['绝技']||'';
    var effectRaw=d['效果']||'';

    // 攻方类型
    var isEnemy=/妖兽|魔族|修士|敌方|BOSS|精英|他宗|变异/.test(fromRaw);
    var isGuest=/临时|队友/.test(fromRaw);
    var fromCls=isEnemy?'enemy':isGuest?'guest':'ally';
    var isToEnemy=/妖兽|魔族|修士|敌方|BOSS|精英|他宗|变异/.test(toRaw);
    var toCls=isToEnemy?'enemy':'ally';

    // 骰值解析（取实际骰值，支持「Z+A=实际骰值:X」格式）
    var actualDice=0;
    var diceDisplay=diceRaw;
    var actualM=String(diceRaw).match(/实际骰值[：:](\d+)/);
    if(actualM){actualDice=parseInt(actualM[1]);}
    else{actualDice=parseInt(String(diceRaw).match(/(\d+)/)?.[1]||'0');}
    var diceType,diceLabel;
    if(actualDice===20){diceType='great';diceLabel='大成功！';}
    else if(actualDice>=12){diceType='hit';diceLabel='命中';}
    else if(actualDice>=6){diceType='graze';diceLabel='勉强';}
    else{diceType='miss';diceLabel='失手';}

    // 伤害解析
    var dmgNum=NaN;
    var dmgM=String(dmgRaw).match(/=\s*\[?(-?\d+(?:\.\d+)?)\]?/)||String(dmgRaw).match(/(-?\d+(?:\.\d+)?)\]?\s*$/);
    if(dmgM) dmgNum=parseFloat(dmgM[1]);
    var isCrit=actualDice===20;

    // 血量变化解析
    var hpOld='',hpNew='';
    var hpM=String(hpRaw).match(/\[?(-?\d+)\]?\s*[→\->]+\s*\[?(-?\d+)\]?/);
    if(hpM){hpOld=hpM[1];hpNew=hpM[2];}
    var newHp=parseFloat(hpNew);
    var maxHp=parseFloat(d['血量上限']||d['上限']||'100');
    var hpCls='safe';
    if(newHp<=0) hpCls='dead';
    else if(newHp/maxHp<0.20) hpCls='crit';
    else if(newHp/maxHp<0.55) hpCls='warn';

    // 检测是否使用绝技
    var hasSkill=!!skillRaw;
    var html=hasSkill
      ?'<div class="combat-wrap skill-wrap" style="padding:10px 14px;">'
      :'<div class="combat-wrap" style="padding:10px 14px;">';
    html+='<div class="section-label atk" style="margin-bottom:4px;">⚡ 攻击结算</div>';
    html+=hasSkill?'<div class="attack-card skill-card">':'<div class="attack-card">';

    // 攻守方
    html+='<div class="atk-header">';
    html+='<span class="atk-from '+fromCls+'">'+esc(fromRaw)+'</span>';
    html+='<span class="atk-arrow">→</span>';
    html+='<span class="atk-to '+toCls+'">'+esc(toRaw)+'</span>';
    html+='</div>';
    if(hasSkill){
      html+='<div class="skill-banner">'
        +'<span class="skill-rune">✦</span>'
        +'<span class="skill-banner-name">'+esc(skillRaw)+'</span>'
        +'<span class="skill-rune">✦</span>'
        +'</div>';
    }
    html+='<div class="divider"></div>';

    // 骰值
    html+='<div class="dice-row"><span class="dice-label">D20</span>';
    html+='<span class="dice-badge '+diceType+'">🎲 '+esc(diceDisplay)+' <span style="font-size:.82em;opacity:.7;">'+diceLabel+'</span></span>';
    html+='</div>';

    // 伤害
    if(dmgRaw){
      var formula=dmgRaw.replace(/=\s*-?\d+(?:\.\d+)?\s*$/,'').trim();
      html+='<div class="dmg-row">';
      if(formula) html+='<span class="dmg-formula">'+esc(formula)+' =</span>';
      html+='<span class="dmg-box '+(isCrit?'crit':'normal')+'">'
           +(isCrit?'💥 ':'⚔ ')+esc(String(isNaN(dmgNum)?dmgRaw:Math.abs(Math.round(dmgNum))))
           +'</span>';
      html+='</div>';
    }

    // 血量变化
    if(hpOld||hpNew){
      html+='<div class="hp-row"><span style="color:var(--dim);font-size:.85em;">血量</span>';
      html+='<span class="hp-old">'+esc(hpOld)+'</span>';
      html+='<span class="hp-arrow">→</span>';
      html+='<span class="hp-new '+hpCls+'">'+esc(hpNew)+'</span>';
      if(newHp<=0) html+='<span class="death-tag">💀 陨落</span>';
      html+='</div>';
    }

    // 特殊效果
    if(effectRaw){
      html+='<div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:2px;">';
      String(effectRaw).split(/[，,;；]/).map(function(e){return e.trim();}).filter(Boolean).forEach(function(ef){
        html+='<span style="font-size:.73em;padding:2px 8px;border-radius:4px;background:rgba(155,114,207,0.12);border:1px solid rgba(155,114,207,0.3);color:var(--purple);">'+esc(ef)+'</span>';
      });
      html+='</div>';
    }

    html+='</div></div>';
    return html;
  }

  /* ══ 入口 ══ */
  var reP='battle'+'_panel', reA='battle'+'_attack';
  var re=new RegExp('^<('+reP+'|'+reA+')>([\\s\\S]*?)<\\/('+reP+'|'+reA+')>$');
  var m=raw.match(re);
  var result='';
  if(m){
    if(m[1]===reP) result=renderPanel(m[2]);
    else result=renderAttack(m[2]);
  } else {
    result='<div class="combat-wrap" style="color:var(--dim);padding:10px;font-size:.85em;font-family:monospace;">[战斗面板解析失败]</div>';
  }
  document.getElementById('output').innerHTML=result;
})();
</script>
