    resClass='success';
  if(resultRaw.indexOf('失败')>=0||resultRaw.indexOf('错失')>=0) resClass='fail';
  if(total===20||resultRaw.indexOf('绝世')>=0||resultRaw.indexOf('大成功')>=0) resClass='great';
  if(isBreak&&resClass==='success'&&total>=17) resClass='great';

  // 机缘等级（1~5）
  var tierLevel=0;
  if(isChance){
    if(total>=20) tierLevel=5;
    else if(total>=16) tierLevel=4;
    else if(total>=11) tierLevel=3;
    else if(total>=6) tierLevel=2;
    else tierLevel=1;
  }
  var tierLabels=['错失','普通','良好','优质','绝世'];
  var TIER_ICONS=['💨','📦','✨','🌟','💎'];

  // 突破阈值解析 "D20≥N（XX%）"
  var threshNum=0,threshPct='';
  if(threshold){
    var tm=threshold.match(/≥\s*(\d+)/);
    if(tm) threshNum=parseInt(tm[1]);
    var pm=threshold.match(/（(\d+%)）|\((\d+%)\)/);
    if(pm) threshPct=(pm[1]||pm[2]);
  }

  // 结果文字
  var resultTxt=resultRaw||'';
  if(!resultTxt){
    if(isBreak) resultTxt=total>=threshNum?'突破成功':'突破失败';
    else if(isChance) resultTxt=tierLabels[tierLevel-1]||'—';
  }
  var resultIcon=resClass==='great'?'💥':resClass==='success'?'✦':resClass==='fail'?'✗':'⚔';

  var html='<div class="card result-'+resClass+'">';

  // 标题行
  html+='<div class="hdr">';
  html+='<span class="type-tag '+(isBreak?'type-break':'type-chance')+'">'
    +(isBreak?'⚡ 突破检定':'🎲 机缘判定')+'</span>';
  html+='<div><span class="disciple-tag">'+esc(disciple)+'</span>'
    +(realm?'<span class="realm-tag">'+esc(realm)+'</span>':'')+'</div>';
  html+='</div>';

  // 骰子区
  html+='<div class="dice-area">';
  // 骰子面（D20标签移到上方）
  html+='<div style="display:flex;flex-direction:column;align-items:center;gap:6px">';
  html+='<span style="font-size:.6em;color:var(--dim);font-family:monospace;letter-spacing:.1em;">D20</span>';
  html+='<div class="dice-face '+resClass+'">'+diceBase+'</div>';
  html+='</div>';
  // 计算行：带标注的 骰值 + 气运 = 合计
  html+='<div class="dice-calc">';
  html+='<div class="calc-row" style="align-items:flex-end;gap:5px;">';
  if(bonus>0){
    html+='<span class="calc-plus" style="margin-bottom:2px;">+</span>';
    html+='<div style="display:flex;flex-direction:column;align-items:center;gap:2px">';
    html+='<span style="font-size:.55em;color:var(--dim);font-family:monospace;">气运</span>';
    html+='<span class="calc-bonus">'+bonusDisplay+'</span>';
    html+='</div>';
    html+='<span class="calc-eq" style="margin-bottom:2px;"> = </span>';
    html+='<div style="display:flex;flex-direction:column;align-items:center;gap:2px">';
    html+='<span style="font-size:.55em;color:var(--dim);font-family:monospace;">合计</span>';
    html+='<span class="calc-total '+resClass+'">'+totalDisplay+'</span>';
    html+='</div>';
  }else{
    html+='<span class="calc-plus" style="margin-bottom:2px;">+</span>';
    html+='<div style="display:flex;flex-direction:column;align-items:center;gap:2px">';
    html+='<span style="font-size:.55em;color:var(--dim);font-family:monospace;">气运</span>';
    html+='<span class="calc-bonus" style="color:var(--dim);">0</span>';
    html+='</div>';
    html+='<span class="calc-eq" style="margin-bottom:2px;"> = </span>';
    html+='<div style="display:flex;flex-direction:column;align-items:center;gap:2px">';
    html+='<span style="font-size:.55em;color:var(--dim);font-family:monospace;">合计</span>';
    html+='<span class="calc-total '+resClass+'">'+totalDisplay+'</span>';
    html+='</div>';
  }
  html+='</div>';
  html+='</div>';
  html+='</div>';

  // 机缘：区间条
  if(isChance&&tierLevel>0){
    html+='<div class="tier-bar">';
    for(var i=1;i<=5;i++){
      html+='<div class="tier-item'+(i<=tierLevel?' active-'+i:'')+'" title="'+tierLabels[i-1]+'"></div>';
    }
    html+='</div>';
    html+='<div class="tier-labels"><span>错失</span><span>普通</span><span>良好</span><span>优质</span><span>绝世</span></div>';
  }

  // 突破：阈值说明
  if(isBreak&&threshNum>0){
    html+='<div class="threshold-row">';
    html+='<span class="threshold-lbl">成功阈值</span>';
    html+='<span class="threshold-val">D20 ≥ '+threshNum+'</span>';
    if(threshPct) html+='<span class="threshold-pct">('+threshPct+')</span>';
    if(hasCave) html+='<span class="cave-bonus">🔮 闭关洞府 +2</span>';
    html+='</div>';
  }

  // 结果条
  var rIcon={'great':'💥 ','success':'✦ ','fail':'✗ ','pending':'⚔ '}[resClass]||'';
  html+='<div class="result-bar '+resClass+'">'+rIcon+esc(resultTxt)+'</div>';

  // 获得内容
  if(gainRaw){
    html+='<div class="context-block" style="border-left-color:rgba(200,168,75,0.4);margin-top:6px"><span style="font-size:.65em;color:var(--gold);display:block;margin-bottom:3px">✦ 获得</span>'+esc(gainRaw)+'</div>';
  }
  // 机缘名已在标题行右侧显示，不重复渲染

  html+='</div>';
  document.getElementById('root').innerHTML=html;
})();
</script>
</body>
</html>
