  border:1px solid rgba(155,114,207,0.3);font-weight:600;
}
.duty-empty{font-size:.65em;color:var(--text-dim);font-style:italic;}
.duty-drag-hint{font-size:.55em;color:rgba(155,114,207,0.5);margin-top:1px;}

/* ── 弟子列表 ── */
.disciple-table{width:100%;border-collapse:separate;border-spacing:0 6px;font-size:.88em;}
.disciple-table th{padding:0 12px 6px;text-align:left;color:var(--text-dim);font-size:.7em;letter-spacing:.08em;font-weight:600;white-space:nowrap;}
.disc-row{background:rgba(255,255,255,0.02);cursor:pointer;transition:all .2s;}
.disc-row td{padding:10px 12px;border-top:1px solid rgba(255,255,255,0.03);border-bottom:1px solid rgba(255,255,255,0.03);}
.disc-row td:first-child{border-left:2px solid transparent;border-top-left-radius:7px;border-bottom-left-radius:7px;}
.disc-row td:last-child{border-top-right-radius:7px;border-bottom-right-radius:7px;}
.disc-row:hover{background:rgba(200,168,75,0.04);}
.disc-row:hover td:first-child{border-left-color:var(--gold-dim);}
.disc-row.active{background:linear-gradient(90deg,rgba(200,168,75,0.06) 0%,rgba(255,255,255,0.02) 100%);}
.disc-row.active td:first-child{border-left-color:var(--gold);}

/* 移动端专属数据标签 (PC端隐藏) */
.m-label { display: none; }

/* 头像 */
.avatar-box{
  width:38px;height:38px;border-radius:6px;flex-shrink:0;
  background:rgba(200,168,75,0.1);border:1px solid var(--ink-border);
  display:inline-flex;align-items:center;justify-content:center;
  overflow:hidden;position:relative;
}
.avatar-box img{width:100%;height:100%;object-fit:cover;border-radius:5px;}
.avatar-box .av-initial{font-size:1em;font-weight:700;color:var(--gold);}

/* 修为进度 */
.realm-badge{
  font-size:.8em;padding:2px 6px;border-radius:4px;
  background:rgba(200,168,75,0.1);color:var(--gold);
  border:1px solid rgba(200,168,75,0.2);white-space:nowrap;font-family:monospace;
}
.prog-bar-wrap{width:60px;height:3px;background:rgba(255,255,255,0.06);border-radius:2px;overflow:hidden;margin-top:3px;}
.prog-fill{height:100%;border-radius:2px;background:linear-gradient(90deg,rgba(200,168,75,0.5),var(--gold));box-shadow:0 0 4px rgba(200,168,75,0.4);}

/* 血量 */
.hp-wrap{display:flex;align-items:center;gap:6px;}
.hp-bar{width:55px;height:4px;background:rgba(255,255,255,0.06);border-radius:2px;overflow:hidden;}
.hp-fill{height:100%;border-radius:2px;transition:width .4s ease;}
.hp-text{font-size:.85em;font-family:monospace;color:var(--text);min-width:42px;}
.hp-text.crit{color:var(--crimson);animation:pulse-crit 1.2s infinite;}
@keyframes pulse-crit{0%,100%{text-shadow:0 0 4px var(--crimson);}50%{text-shadow:0 0 10px var(--crimson);}}

/* 忠诚度 */
.loyalty-wrap{display:flex;align-items:center;gap:5px;min-width:70px;}
.loyalty-bar{flex:1;height:4px;background:rgba(255,255,255,0.06);border-radius:2px;overflow:hidden;min-width:30px;}
.loyalty-fill{height:100%;border-radius:2px;transition:width .4s;}
.loyalty-text{font-size:.85em;font-family:monospace;min-width:20px;text-align:right;}

/* 贡献点 */
.contrib{font-size:.9em;font-family:monospace;font-weight:700;color:var(--cyan);}

/* 详情展开 */
.detail-row{display:none;}
.detail-cell{padding:0 0 10px !important;border:none !important;}
.detail-panel{
  margin:0 6px;padding:14px;
  border-radius:0 0 8px 8px;
  border:1px dashed rgba(200,168,75,0.15);
  border-top:none;
  background:rgba(12,10,22,0.95);
  animation:slideDown .25s ease forwards;
  background-size:cover;background-position:center;
}
@keyframes slideDown{from{opacity:0;transform:translateY(-6px);}to{opacity:1;transform:translateY(0);}}

.detail-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;}
.d-item{padding:9px 10px;border-radius:6px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);display:flex;flex-direction:column;gap:4px;box-sizing:border-box;}
.d-item.span2{grid-column:span 2;}
.d-item.span3{grid-column:span 3;}
.d-item.span4{grid-column:span 4;}
.d-item.span5{grid-column:span 5;}
.d-label{font-size:.72em;color:var(--text-dim);letter-spacing:.08em;}
.d-val{font-size:.9em;color:var(--text);line-height:1.5;word-break:break-all;}
.d-val.hl{font-family:monospace;font-weight:700;font-size:1em;}

/* 五维格 */
.wuwei-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin-top:2px;}
.ww-item{display:flex;flex-direction:column;gap:2px;align-items:center;padding:5px 4px;border-radius:5px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);}
.ww-name{font-size:.6em;color:var(--text-dim);letter-spacing:.05em;}
.ww-val{font-size:.95em;font-family:monospace;font-weight:700;}
.ww-val.force{color:#e07050;}
.ww-val.body{color:#5090d0;}
.ww-val.spirit{color:var(--purple);}
.ww-val.insight{color:var(--jade);}
.ww-val.luck{color:var(--gold);}
.ww-bar{width:100%;height:2px;background:rgba(255,255,255,0.06);border-radius:1px;overflow:hidden;}
.ww-fill{height:100%;border-radius:1px;}

/* 状态标签（地点） */
.loc-tag{font-size:.68em;padding:3px 8px;border-radius:8px;font-family:monospace;white-space:nowrap;display:inline-block;}
.loc-sect{background:rgba(94,207,160,0.1);color:var(--jade);border:1px solid rgba(94,207,160,0.25);}
.loc-duty{background:rgba(155,114,207,0.1);color:var(--purple);border:1px solid rgba(155,114,207,0.25);}
.loc-other{background:rgba(200,168,75,0.1);color:var(--gold);border:1px solid rgba(200,168,75,0.2);}

/* 外貌/背景文本截断 */
.long-text{font-size:.85em;color:#b0a898;line-height:1.6;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;}

/* ==========================================================================
   ====== 响应式适配核心 (Mobile & Tablet) ====== 
   ========================================================================== */

/* Tablet & 小尺寸桌面 (Max-width 850px) */
@media(max-width: 850px) {
  .facility-grid { grid-template-columns: repeat(3, 1fr); }
  .detail-grid { grid-template-columns: repeat(3, 1fr); }
  .d-item.span4, .d-item.span5 { grid-column: span 3; }
  .d-item.span3 { grid-column: span 3; }
}

/* 大屏PC (min-width: 851px) - 覆盖回多列 */
@media(min-width: 851px) {
  .facility-grid { grid-template-columns: repeat(4, 1fr); }
}

/* 窄屏设备 (Max-width: 700px) */
@media(max-width: 700px){
  .sect-wrap{padding:12px;gap:14px;}
  .overview-grid{grid-template-columns:repeat(2,1fr);}
  .facility-grid{grid-template-columns:repeat(2,1fr);}
  .duty-grid{grid-template-columns:repeat(2,1fr);}

  .detail-grid{grid-template-columns:repeat(2,1fr);}
  .d-item.span2,.d-item.span3,.d-item.span4,.d-item.span5 { grid-column: span 2; }
  .wuwei-grid{grid-template-columns:repeat(3,1fr);}

  /* 允许指示灯栏隐藏竖线 */
  .dot-sep { display: none; }
  .status-dots { justify-content: center; }

  /* 轻微缩小表格字体 */
  .disciple-table { font-size: 0.8em; }
}

/* 极窄屏幕/移动端最终降级 (Max-width: 550px) */
@media(max-width: 550px){
  .overview-grid{grid-template-columns:1fr 1fr;}
  .facility-grid{grid-template-columns:repeat(2,1fr);}
  .duty-grid{grid-template-columns:repeat(2,1fr);}

  /* 详情内部完全单列 */
  .detail-grid { grid-template-columns: 1fr; }
  .d-item.span2,.d-item.span3,.d-item.span4,.d-item.span5 { grid-column: span 1; }
  .wuwei-grid{grid-template-columns:repeat(5,1fr); gap: 2px;}

 /* 废弃 Table 的同行布局，转化为响应式网格流 */
  .disciple-table thead { display: none; }
  .disciple-table, .disciple-table tbody { 
    display: block; width: 100%; box-sizing: border-box; 
  }
  .detail-row { display: none; } /* 重新声明：确保详情卡片在移动端默认隐藏 */

  /* 唤醒移动端专属标签 */
  .m-label { 
    display: block; 
    font-size: 0.72em; 
    color: var(--text-dim); 
    margin-bottom: 4px; 
    letter-spacing: 0.05em; 
  }

  /* 单个弟子卡片强制两列均分布局，吃满左右空间 */
  .disc-row {
    display: grid;
    grid-template-columns: 1fr 1fr; /* 平分左右两侧 */
    gap: 12px;
    padding: 14px;
    margin-bottom: 12px;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.05);
    background: rgba(255,255,255,0.02);
  }
  .disc-row:hover { border-color: var(--gold-dim); }
  .disc-row.active { border-color: var(--gold); }

  /* 卡片内部数据块 (原先的td)，垂直居左对齐 */
  .disc-row td {
    display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
    border: none !important; padding: 0 !important; width: 100% !important; box-sizing: border-box;
  }

  /* 头像栏占满顶部整行 */
  .disc-row td:first-child {
    grid-column: span 2;
    border-bottom: 1px dashed rgba(255,255,255,0.1) !important;
    padding-bottom: 12px !important; margin-bottom: 2px;
  }

  /* 逐出按钮：推到右侧对齐 */
  .disc-row td:last-child {
    align-items: flex-end; 
    justify-content: flex-end;
  }

  /* 释放进度条的死板宽度，让它随网格自适应 */
  .prog-bar-wrap, .hp-bar, .loyalty-bar { width: 100%; max-width: 100%; }
  .hp-wrap, .loyalty-wrap { width: 100%; justify-content: flex-start; }

  /* 详情下拉框，重新撑满两列宽度 */
  .detail-row { display: none; } 
  .detail-row.active { display: block; }
  .detail-row td { grid-column: span 2; width: 100% !important; display: block; }
  .detail-panel { margin: 0; border-radius: 8px; border-top: 1px dashed rgba(200,168,75,0.15); }
}

/* 更小屏特化 (Max-width: 400px) */
@media(max-width: 400px){
  /* overview-grid 保持两列，不降为单列 */
  .wuwei-grid { grid-template-columns: repeat(3, 1fr); }
}
