<script>
const _AVATAR_KEY='sect_avatar_cache';
function _getLS(){try{if(window.parent&&window.parent.localStorage)return window.parent.localStorage;}catch(e){}try{return localStorage;}catch(e){}return null;}
function _loadAvatars(){try{const s=_getLS();return s?JSON.parse(s.getItem(_AVATAR_KEY)||'{}'):{};}catch(e){return{};}}
const _avatarCache=_loadAvatars();

function fillTA(text){
  try{
    if(typeof window.sendTextareaValue==='function'){window.sendTextareaValue(text);return;}
    const ta=window.parent&&window.parent.document?window.parent.document.querySelector('#send_textarea,textarea#chat_input,textarea[name="chat_input"]'):null;
    if(ta){const old=ta.value;ta.value=old?old+'\n'+text:text;ta.dispatchEvent(new Event('input',{bubbles:true}));ta.focus();return;}
  }catch(e){}
  try{navigator.clipboard.writeText(text);}catch(e2){}
}

function appendTA(text){
  try{
    const ta=window.parent&&window.parent.document?window.parent.document.querySelector('#send_textarea,textarea#chat_input,textarea[name="chat_input"]'):null;
    if(ta){
      const cur=ta.value.trim();
      ta.value=cur?cur+'\n'+text:text;
      ta.dispatchEvent(new Event('input',{bubbles:true}));ta.focus();return;
    }
  }catch(e){}
  fillTA(text);
}
function fillInputTA(text){
  try{
    const ta=window.parent&&window.parent.document?window.parent.document.querySelector('#send_textarea,textarea#chat_input,textarea[name="chat_input"]'):null;
    if(ta){
      ta.value=text;
      ta.dispatchEvent(new Event('input',{bubbles:true}));ta.focus();return;
    }
  }catch(e){}
  fillTA(text);
}

