    d={
      世界:{叙事时间:'青玄历 元年 春 二月 初三',当前时辰:'辰时',天气:'晴',本月招募已触发:false,本月秘境已生成:false,本月秘境已探索:false},
      宗派:{宗派名:'（待命名）',宗派阶位:1,宗派名号:'散修聚点',宗派声望:0,宗派规模:2,
            宗派规模上限:10,内门弟子上限:2,在籍内门弟子数:0,当前执事:'（待选择）',
            宗门灵材库:50,宗门职务:{},宗门设施:{}},
      内门弟子:{}
    };
  }

  // ── 宗门总览 ──
  const sectName=_.get(d,'宗派.宗派名','未命名宗门');
  const sectRank=_.get(d,'宗派.宗派阶位',1);
  const SECT_TITLES=['','散修聚点','小宗小派','立宗之基','地方名宗','区域强宗','一方霸主','大陆名宗','顶级势力','修仙圣地','仙门正宗'];
  const sectTitle=SECT_TITLES[sectRank]||'散修聚点';
  const prestige=_.get(d,'宗派.宗派声望',0);
  const discipleNow=_.get(d,'宗派.在籍内门弟子数',0);
  const discipleMax=_.get(d,'宗派.内门弟子上限',2);
  const storehouse=_.get(d,'宗派.宗门灵材库',0);
  const worldTime=_.get(d,'世界.叙事时间','—');
  const loyalTriggered=_.get(d,'世界.今日忠诚度事件已触发',false);
  const recruitTriggered=_.get(d,'世界.本月招募已触发',false);
  const realmTriggered=_.get(d,'世界.本月秘境已探索',false);
  const realmGenerated=_.get(d,'世界.本月秘境已生成',false);
  const realmName=_.get(d,'秘境.秘境名称','待勘探');
  const realmDisciples=_.get(d,'秘境.分配弟子',[]);
  const realmHasDisciples=Array.isArray(realmDisciples)&&realmDisciples.filter(x=>x&&!x.startsWith('$')).length>0;
  const realmActive=realmGenerated||realmHasDisciples||(realmName&&realmName!=='待勘探'&&realmName!=='');
  const tourneyTriggered=_.get(d,'宗门大比.本届状态','未开始')!=='未开始';
  const worldShichen=_.get(d,'世界.当前时辰','');
  const scale=_.get(d,'宗派.宗派规模',0);
  const scaleMax=_.get(d,'宗派.宗派规模上限',10);

  // 声望到下一阶
  const prestigeThresholds=[0,10000,40000,100000,200000,400000,700000,1200000,1900000,3100000];
  const nxtThr=prestigeThresholds[sectRank]||0;
  const prestigePct=nxtThr>0?Math.min(100,Math.max(0,prestige/nxtThr*100)):100;

  $('#ov-name').text(sectName+' · '+sectTitle);
  // 状态灯
  $('#dot-loyal').css({'background':loyalTriggered?'var(--jade)':'var(--crimson)','box-shadow':loyalTriggered?'0 0 6px var(--jade)':'0 0 6px var(--crimson)'});
