  $('#dot-realm').css({'background':realmActive?'var(--jade)':'var(--crimson)','box-shadow':realmActive?'0 0 6px var(--jade)':'0 0 6px var(--crimson)'});
  $('#dot-realm-txt').text(realmActive?'已触发':'未触发').css('color',realmActive?'var(--jade)':'var(--crimson)');
  $('#dot-tourney').css({'background':tourneyTriggered?'var(--jade)':'var(--crimson)','box-shadow':tourneyTriggered?'0 0 6px var(--jade)':'0 0 6px var(--crimson)'});
  $('#dot-tourney-txt').text(tourneyTriggered?'已开启':'未开始').css('color',tourneyTriggered?'var(--jade)':'var(--crimson)');
  $('#ov-rank').text(sectRank+'阶');
  const nxtPrestige=nxtThr>0?nxtThr.toLocaleString():'顶阶';
  $('#ov-prestige').text(prestige.toLocaleString()+'/'+(nxtThr>0?nxtThr.toLocaleString():'—'));
