  $('#ov-disciple').text(discipleNow+'/'+discipleMax+'人');
    $('#ov-scale').text(scale);
  $('#ov-store').text(storehouse.toLocaleString()+' 灵材');
  $('#ov-time').text(worldTime+(worldShichen?' · '+worldShichen:''));

  const BASE_COST=[0,350,4290,9110,8580,17870,34320,60060,102960,173740];
  const REALM_MID=[0,100,600,850,600,1000,1600,2400,3600,5400,8000];
  const UNIFIED_COST=BASE_COST[sectRank]||350;
  function getFacilityDetail(key,lv){
    const disciples=sectRank*2;
    const fullMonthly=disciples*REALM_MID[Math.min(sectRank,10)];
    const WPN=[0,50,450,800,850,1500,2800,4800,8500,14500];
