    const LAW=[0,0,0,0,0,6000,14000,28800,59500,116000];
    const r=Math.min(sectRank,9);
    function jlDetail(k,n){
      switch(k){
        case '聚灵殿':{if(!n)return '建设后对低阶弟子修炼加速';const b1=(((1+n*1*0.08)-1)*100).toFixed(0);const b2=(((1+n*2*0.08)-1)*100).toFixed(0);return n+'级 · 差1阶+'+b1+'% / 差2阶+'+b2+'%';}
        case '灵田':{if(!n)return '建设后每月被动产出灵材';const prod=Math.floor(fullMonthly*n*0.015);return n+'级 · 每月+'+prod+' 灵材（被动）';}
