        </div>

        <div class=\"d-item\">
          <div class=\"d-label\">❤ 忠诚触点</div>
          ${hasLoyalTrigger?`<div style=\"margin-top:4px;display:flex;flex-direction:column;gap:5px;\">${loyalTrigger?`<div style=\"font-size:.68em;line-height:1.5;\"><span style=\"color:var(--text-dim);\">触动：</span>${loyalTrigger}</div>`:''}${loyalProbe?`<div style=\"font-size:.68em;line-height:1.5;\"><span style=\"color:var(--text-dim);\">试探：</span>${loyalProbe}</div>`:''}${loyalChill?`<div style=\"font-size:.68em;line-height:1.5;\"><span style=\"color:var(--text-dim);\">寒心：</span>${loyalChill}</div>`:''}</div>`:'<div style=\"font-size:.68em;color:var(--text-dim);margin-top:4px;font-style:italic;\">— 未知 —</div>'}
        </div>

      </div>
    </div>
        </td></tr>`);
    if(avatar){
      $detail.find('.detail-panel').css('background-image',`linear-gradient(rgba(10,8,20,0.92),rgba(10,8,20,0.92)),url('${avatar}')`);
    }
    $tbody.append($row).append($detail);
    $row.find('.expel-btn').on('click',function(e){
      e.stopPropagation();
      var n=$(this).data('name');
      if(confirm('确定将【'+n+'】逐出内门？此操作不可撤销。')){
        fillInputTA('宗门逐出弟子。remove /内门弟子/'+n+'\n\n请描写将【'+n+'】逐出内门的叙事，并删除该弟子的所有变量。在籍弟子数-1。');
      }
    });
    $row.on('click',function(){
      const $dr=$('#dr-'+name);
      const open=$(this).hasClass('active');
      $tbody.find('.disc-row').removeClass('active');
      $tbody.find('.detail-row').hide();
      if(!open){$(this).addClass('active');$dr.show();}
    });
  });
  setTimeout(()=>{ },50);
}

async function init(){
  try{await waitGlobalInitialized('Mvu');if(typeof eventOn==='function')eventOn(Mvu.events.VARIABLE_UPDATE_ENDED,typeof errorCatched==='function'?errorCatched(render):render);}
  catch(e){console.log('非ST环境');}
  render();
}
$(typeof errorCatched==='function'?errorCatched(init):init);
</script>
