import 'https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate/artifact/bundle.js';

// ============================================================
// 了不起的宗门模拟器 · MVU变量脚本
// 功能：
//   1. 新建聊天时自动写入初始 stat_data（对应 initvar 结构）
//   2. 弟子字段防御补全（防止AI insert时漏填字段）
//   3. 在籍弟子数自动统计
//   4. 忠诚度/修为进度值钳制（防止越界）
//   5. 声望驱动规模上限自动更新
// ============================================================

$(() => {

  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, errorCatched((variables) => {
    // ⚠️ 额外API模式下跳过，避免重复执行
    if (Mvu.isDuringExtraAnalysis()) return;
    let data = variables.stat_data;

    // ── 新建聊天时 stat_data 为空，写入初始结构 ──────────────
    if (!data) {
      variables.stat_data = {
        世界: {
          叙事时间: '青玄历 元年 春 二月 初三',
          当前时辰: '辰时',
          天气: '晴',
          本月招募已触发: false
        },
        宗派: {
          宗派名: '（待命名）',
          宗派阶位: 1,
          宗派名号: '无名小宗',
          宗派声望: 0,
          宗派规模: 2,
          宗派规模上限: 10,
          内门弟子上限: 2,
          在籍内门弟子数: 0,
          宗规: '',
          宗规更新时间: '',
          当前执事: '',
          宗门灵材库: 50,
          宗门职务: {
            掌库执事: '素问',
            护山长老: '',
            传功师兄: '',
            引路使者: ''
          },
          宗门设施: {
            聚灵殿: { 已建设: false, 等级: 0 },
            灵田: { 已建设: false, 等级: 0 },
            疗伤院: { 已建设: false, 等级: 0 },
            精炼坊: { 已建设: false, 等级: 0 },
            藏经阁: { 已建设: false },
            炼丹房: { 已建设: false },
            铸器坊: { 已建设: false },
            灵兽府: { 已建设: false },
            试炼场: { 已建设: false },
            闭关洞府: { 已建设: false },
            膳堂: { 已建设: false },
            议事堂: { 已建设: false }
          }
        },
        宗门大比: {
          本届状态: '未开始',
          本届年份: '',
          本届宗门阶位: 1,
          本届参赛宗门数: 0,
          本届上阵弟子: [],
          本届赛程: [],
          本届名次: '',
          已获大比晋级资格: false
        },
        秘境: {
          秘境名称: '待勘探',
          秘境等级: '—',
          秘境等级值: 0,
          分配弟子: [],
          灵材上限: 0,
          本次事件数: 0
        },
        内门弟子: {}
      };
      data = variables.stat_data;
    }

    const disciples = _.get(data, '内门弟子', {});

    // ── 遍历所有内门弟子做字段防御补全 ──────────────────────
    _.forEach(Object.keys(disciples), (name) => {
      if (!name || name.startsWith('$')) return;
      const disc = _.get(data, `内门弟子.${name}`);
      if (!disc || typeof disc !== 'object') return;

      // 血量字段防御
      const hpField = _.get(data, `内门弟子.${name}.血量`);
      if (!hpField || typeof hpField !== 'object') {
        _.set(data, `内门弟子.${name}.血量`, { 当前值: 80, 上限: 80, 下降率: 0 });
      } else {
        if (_.get(data, `内门弟子.${name}.血量.当前值`) === undefined)
          _.set(data, `内门弟子.${name}.血量.当前值`, 80);
        if (_.get(data, `内门弟子.${name}.血量.上限`) === undefined)
          _.set(data, `内门弟子.${name}.血量.上限`, 80);
      }

      // 血量钳制
      const hpNow = Number(_.get(data, `内门弟子.${name}.血量.当前值`, 0));
      const hpMax = Number(_.get(data, `内门弟子.${name}.血量.上限`, 80));
      _.set(data, `内门弟子.${name}.血量.当前值`, _.clamp(hpNow, 0, hpMax));

      // 修为进度防御
      if (!_.get(data, `内门弟子.${name}.修为进度`) || typeof _.get(data, `内门弟子.${name}.修为进度`) !== 'object')
        _.set(data, `内门弟子.${name}.修为进度`, { 当前值: 0 });
      if (_.get(data, `内门弟子.${name}.修为进度.当前值`) === undefined)
        _.set(data, `内门弟子.${name}.修为进度.当前值`, 0);

      // 忠诚度防御与钳制
      if (!_.get(data, `内门弟子.${name}.忠诚度`) || typeof _.get(data, `内门弟子.${name}.忠诚度`) !== 'object')
        _.set(data, `内门弟子.${name}.忠诚度`, { 当前值: 0 });
      const loyal = Number(_.get(data, `内门弟子.${name}.忠诚度.当前值`, 0));
      _.set(data, `内门弟子.${name}.忠诚度.当前值`, _.clamp(loyal, 0, 100));

      // 绝技防御
      const skill = _.get(data, `内门弟子.${name}.绝技`);
      if (!skill || typeof skill !== 'object') {
        _.set(data, `内门弟子.${name}.绝技`, { 名称: '', 简述: '', 本场可使用次数: 1, 本阶已领悟: false });
      } else {
        if (_.get(data, `内门弟子.${name}.绝技.本场可使用次数`) === undefined)
          _.set(data, `内门弟子.${name}.绝技.本场可使用次数`, 1);
      }

      // 贡献点防御
      if (_.get(data, `内门弟子.${name}.贡献点`) === undefined)
        _.set(data, `内门弟子.${name}.贡献点`, 0);

      // 背包灵材防御
      const bag = _.get(data, `内门弟子.${name}.背包灵材`);
      if (!bag || typeof bag !== 'object')
        _.set(data, `内门弟子.${name}.背包灵材`, { 当前量: 0, 上限: 0 });

      // 五维防御
      const wuwei = _.get(data, `内门弟子.${name}.五维`);
      if (!wuwei || typeof wuwei !== 'object')
        _.set(data, `内门弟子.${name}.五维`, { 力量: 0, 体质: 0, 灵力: 0, 悟性: 0, 气运: 0 });

      // 修为等级值/修为层数防御
      if (_.get(data, `内门弟子.${name}.修为等级值`) === undefined)
        _.set(data, `内门弟子.${name}.修为等级值`, 1);
      if (_.get(data, `内门弟子.${name}.修为层数`) === undefined)
        _.set(data, `内门弟子.${name}.修为层数`, 1);

      // 善恶值防御与钳制
      if (_.get(data, `内门弟子.${name}.善恶值`) === undefined)
        _.set(data, `内门弟子.${name}.善恶值`, 0);
      const align = Number(_.get(data, `内门弟子.${name}.善恶值`, 0));
      _.set(data, `内门弟子.${name}.善恶值`, _.clamp(align, -100, 100));

      // 当前地点防御
      const loc = _.get(data, `内门弟子.${name}.当前地点`);
      if (!loc || typeof loc !== 'object')
        _.set(data, `内门弟子.${name}.当前地点`, { 名称: '宗门大堂', 等级: '宗门' });
      else {
        if (_.get(data, `内门弟子.${name}.当前地点.名称`) === undefined)
          _.set(data, `内门弟子.${name}.当前地点.名称`, '宗门大堂');
        if (_.get(data, `内门弟子.${name}.当前地点.等级`) === undefined)
          _.set(data, `内门弟子.${name}.当前地点.等级`, '宗门');
      }

      // 攻击法器防御
      const atkW = _.get(data, `内门弟子.${name}.攻击法器`);
      if (!atkW || typeof atkW !== 'object')
        _.set(data, `内门弟子.${name}.攻击法器`, { 名称: '', 攻击力: 0 });

      // 护身法器防御
      const defW = _.get(data, `内门弟子.${name}.护身法器`);
      if (!defW || typeof defW !== 'object')
        _.set(data, `内门弟子.${name}.护身法器`, { 名称: '', 血量加成: 0 });

      // 灵兽防御
      const beast = _.get(data, `内门弟子.${name}.灵兽`);
      if (!beast || typeof beast !== 'object')
        _.set(data, `内门弟子.${name}.灵兽`, { 名称: '', 品阶: '', 攻击加成: 0, 血量加成: 0, 外貌特征: '' });

      // 携带丹药防御
      const pill = _.get(data, `内门弟子.${name}.携带丹药`);
      if (!pill || typeof pill !== 'object')
        _.set(data, `内门弟子.${name}.携带丹药`, { 名称: '', 品级: '', 回血量: 0 });

      // 横向关系防御
      if (!_.get(data, `内门弟子.${name}.横向关系`) || typeof _.get(data, `内门弟子.${name}.横向关系`) !== 'object')
        _.set(data, `内门弟子.${name}.横向关系`, {});

      // 头像URL防御
      if (_.get(data, `内门弟子.${name}.头像URL`) === undefined)
        _.set(data, `内门弟子.${name}.头像URL`, '');
    });

    // ── 自动统计在籍内门弟子数 ──────────────────────────────
    const validCount = Object.keys(disciples).filter(k => !k.startsWith('$')).length;
    _.set(data, '宗派.在籍内门弟子数', validCount);

    // ── 声望驱动规模上限自动更新 ────────────────────────────
    const prestige = Number(_.get(data, '宗派.宗派声望', 0));
    _.set(data, '宗派.宗派规模上限', Math.floor(prestige * 0.12) + 10);

  }));

});
